import json, urllib.request, ssl, base64

ctx = ssl._create_unverified_context()
creds = "$elk_user:$elk_pass"
auth = base64.b64encode(creds.encode()).decode()
headers = {"Content-Type": "application/json", "Authorization": f"Basic {auth}"}
errors = []

def es_post(path, body):
    req = urllib.request.Request(
        f"$elk_url{path}",
        data=json.dumps(body).encode(),
        headers=headers,
        method="POST"
    )
    resp = urllib.request.urlopen(req, context=ctx, timeout=20)
    return json.loads(resp.read().decode())

type_summary = {}
ja3_count = 0
snis = []
dns_2lds = []
ja4s = []
user_agents = []
ips_top20 = []

# Query A: type summary
try:
    r = es_post("/haccp-entities-seen/_search", {
        "size": 0,
        "track_total_hits": True,
        "query": {"range": {"first_seen": {"gte": "now-12h"}}},
        "aggs": {"by_type": {"terms": {"field": "entity_type", "size": 10}}}
    })
    for b in r.get("aggs", r.get("aggregations", {})).get("by_type", {}).get("buckets", []):
        type_summary[b["key"]] = b["doc_count"]
    ja3_count = type_summary.get("ja3", 0)
except Exception as e:
    errors.append(f"query_A: {str(e)[:150]}")

# Query B: non-ja3 entity values
NON_JA3 = ["sni", "dns_query_2ld", "ja4", "http_user_agent", "external_dst_ip"]
all_novel_ips = []
try:
    r = es_post("/haccp-entities-seen/_search", {
        "size": 300,
        "query": {"bool": {"filter": [
            {"range": {"first_seen": {"gte": "now-12h"}}},
            {"terms": {"entity_type": NON_JA3}}
        ]}},
        "sort": [{"first_seen": "desc"}],
        "_source": ["entity_type", "entity_value", "first_seen"]
    })
    for h in r.get("hits", {}).get("hits", []):
        src = h.get("_source", {})
        et = src.get("entity_type", "")
        ev = src.get("entity_value", "")
        fs = src.get("first_seen", 0)
        if et == "sni":
            snis.append(ev)
        elif et == "dns_query_2ld":
            dns_2lds.append(ev)
        elif et == "ja4":
            ja4s.append(ev)
        elif et == "http_user_agent":
            user_agents.append(ev)
        elif et == "external_dst_ip":
            all_novel_ips.append({"ip": ev, "first_seen_ms": fs})
except Exception as e:
    errors.append(f"query_B: {str(e)[:150]}")

# Query C: top 20 novel IPs by connection count
if all_novel_ips:
    try:
        ip_list = [x["ip"] for x in all_novel_ips]
        r = es_post("/logs-zeek.haccp-default/_search", {
            "size": 0,
            "track_total_hits": True,
            "query": {"bool": {"filter": [
                {"range": {"@timestamp": {"gte": "now-12h"}}},
                {"terms": {"id_resp_h": ip_list}}
            ]}},
            "aggs": {"by_ip": {"terms": {"field": "id_resp_h", "size": 20}}}
        })
        ip_fs_map = {x["ip"]: x["first_seen_ms"] for x in all_novel_ips}
        for b in r.get("aggs", r.get("aggregations", {})).get("by_ip", {}).get("buckets", []):
            ips_top20.append({
                "ip": b["key"],
                "count": b["doc_count"],
                "first_seen_ms": ip_fs_map.get(b["key"], 0)
            })
    except Exception as e:
        errors.append(f"query_C: {str(e)[:150]}")

total_excluding_ja3 = len(snis) + len(dns_2lds) + len(ja4s) + len(user_agents) + len(all_novel_ips)

print(json.dumps({
    "window_hours": 12,
    "ja3_count": ja3_count,
    "type_summary": type_summary,
    "total_excluding_ja3": total_excluding_ja3,
    "ips_top20": ips_top20,
    "snis": snis,
    "dns_2lds": dns_2lds,
    "ja4s": ja4s,
    "user_agents": user_agents,
    "errors": errors
}))

import json, urllib.request, ssl, base64

upstream = json.loads('''$query_novel_entities.message''')
if isinstance(upstream, str):
    try:
        upstream = json.loads(upstream)
    except:
        upstream = {}

ips_top20 = upstream.get("ips_top20", [])
geoip_errors = []

if not ips_top20:
    print(json.dumps({"ips_enriched": [], "geoip_errors": []}))
    import sys; sys.exit(0)

ctx = ssl._create_unverified_context()
creds = "$elk_user:$elk_pass"
auth = base64.b64encode(creds.encode()).decode()
headers = {"Content-Type": "application/json", "Authorization": f"Basic {auth}"}

pipeline_body = {
    "pipeline": {"processors": [
        {"geoip": {"field": "ip", "target_field": "geo",
                   "properties": ["country_name", "country_iso_code"],
                   "ignore_missing": True}},
        {"geoip": {"field": "ip", "target_field": "asn",
                   "database_file": "GeoLite2-ASN.mmdb",
                   "properties": ["asn", "organization_name"],
                   "ignore_missing": True}}
    ]},
    "docs": [{"_source": {"ip": row["ip"]}} for row in ips_top20]
}

ips_enriched = []
try:
    req = urllib.request.Request(
        "$elk_url/_ingest/pipeline/_simulate",
        data=json.dumps(pipeline_body).encode(),
        headers=headers,
        method="POST"
    )
    resp = urllib.request.urlopen(req, context=ctx, timeout=15)
    sim = json.loads(resp.read().decode())
    for i, doc in enumerate(sim.get("docs", [])):
        src = doc.get("doc", {}).get("_source", {})
        geo = src.get("geo", {})
        asn = src.get("asn", {})
        row = ips_top20[i] if i < len(ips_top20) else {"ip": "?", "count": 0, "first_seen_ms": 0}
        ips_enriched.append({
            "ip": row["ip"],
            "count": row["count"],
            "first_seen_ms": row.get("first_seen_ms", 0),
            "country": geo.get("country_name", "?"),
            "country_iso": geo.get("country_iso_code", "?"),
            "asn": asn.get("asn"),
            "asn_org": asn.get("organization_name", "?")
        })
except Exception as e:
    geoip_errors.append(str(e)[:200])
    for row in ips_top20:
        ips_enriched.append({
            "ip": row["ip"],
            "count": row["count"],
            "first_seen_ms": row.get("first_seen_ms", 0),
            "country": "?", "country_iso": "?", "asn": None, "asn_org": "?"
        })

print(json.dumps({"ips_enriched": ips_enriched, "geoip_errors": geoip_errors}))

import json, datetime

query = json.loads('''$query_novel_entities.message''')
if isinstance(query, str):
    try:
        query = json.loads(query)
    except:
        query = {}

geo = json.loads('''$enrich_geoip.message''')
if isinstance(geo, str):
    try:
        geo = json.loads(geo)
    except:
        geo = {}

ja3_count = query.get("ja3_count", 0)
total = query.get("total_excluding_ja3", 0)
ips = geo.get("ips_enriched", [])
snis = query.get("snis", [])
dns_2lds = query.get("dns_2lds", [])
ja4s = query.get("ja4s", [])
uas = query.get("user_agents", [])
q_errors = query.get("errors", [])
g_errors = geo.get("geoip_errors", [])

KIBANA_URL = "http://10.10.30.25:5601/app/discover#/?_g=(time:(from:now-24h,to:now))&_a=(index:%27logs-zeek.haccp-default%27,query:(language:kuery,query:%27tags:tier2_novel%27))"

def sanitize(s):
    return str(s).replace('"', "'").replace("\\", "")[:200]

def build_list(items, max_show=15, max_chars=80):
    if not items:
        return "_(none)_"
    lines = []
    for item in items[:max_show]:
        v = sanitize(item)
        if len(v) > max_chars:
            v = v[:max_chars-3] + "..."
        lines.append(f"`{v}`")
    if len(items) > max_show:
        lines.append(f"...and {len(items) - max_show} more")
    return "\\n".join(lines)

def build_ip_list(ips):
    if not ips:
        return "_(none)_"
    lines = []
    for row in ips[:20]:
        org = sanitize(row.get("asn_org", "?"))[:40]
        iso = row.get("country_iso", "?")
        lines.append(f"`{row['ip']}` \u00b7 {row['count']} conns \u00b7 {iso} \u00b7 {org}")
    return "\\n".join(lines)

fields = []
if ips:
    fields.append({"name": "\U0001f310 Top IPs by volume", "value": build_ip_list(ips), "inline": False})
if snis:
    fields.append({"name": f"\U0001f512 New SNIs ({len(snis)})", "value": build_list(snis), "inline": False})
if dns_2lds:
    fields.append({"name": f"\U0001f9ed New DNS 2LDs ({len(dns_2lds)})", "value": build_list(dns_2lds), "inline": False})
if ja4s:
    fields.append({"name": f"\U0001f446 New JA4s ({len(ja4s)})", "value": build_list(ja4s), "inline": False})
if uas:
    fields.append({"name": f"\U0001f575 New User-Agents ({len(uas)})", "value": build_list(uas, max_chars=80), "inline": False})

title = f"HACCP Tier2 Digest: {total} new entities (last 12h)"
desc = f"JA3 fingerprints: {ja3_count} new (summary only, see drill-down)"
if total == 0 and ja3_count == 0:
    desc = "No new entities in the last 12h, pipeline healthy"

footer_text = f"WF-HACCP-2 \u00b7 12h window \u00b7 drill: {KIBANA_URL[:80]}..."
all_errors = len(q_errors) + len(g_errors)
if all_errors > 0:
    footer_text += f" \u00b7 \u26a0\ufe0f Partial: {all_errors} query errors"

now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

embed = {
    "title": title[:256],
    "description": desc,
    "color": 3447003,
    "fields": fields,
    "footer": {"text": footer_text[:2048]},
    "timestamp": now
}

body = json.dumps({"embeds": [embed]})
if len(body) > 5500:
    for priority in ["\U0001f575", "\U0001f446", "\U0001f9ed", "\U0001f512"]:
        for i, f in enumerate(embed["fields"]):
            if priority in f["name"]:
                embed["fields"][i]["value"] = "...truncated to fit Discord embed limit"
                body = json.dumps({"embeds": [embed]})
                if len(body) <= 5500:
                    break
        if len(body) <= 5500:
            break

print(json.dumps({"embed_body": body}))
